// QSPI_XIP_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module QSPI_XIP_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [7:0] c_div,
  input logic  c_quad,
  input logic [7:0] c_pc_cmd,
  input logic  c_pc_has_addr,
  input logic [2:0] c_pc_nwr,
  input logic [2:0] c_pc_nrd,
  input logic [23:0] c_pc_addr,
  input logic [31:0] c_pc_wdata,
  input logic  c_pc_start,
  input logic [31:0] c_pc_rdata,
  input logic  c_pc_busy,
  input logic [15:0] c_xip_cmds,
  input logic [15:0] c_xip_beats,
  input logic  c_pc_done
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 14;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:13];          // model of every stored word
  logic [0:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_pc_done) m_set[0] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h101;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h1FF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h7FFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 9) ? PWDATA & m_be & 32'h1 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h5C530100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return 0;
      10: return (32'(c_pc_rdata) << 0);
      11: return (32'(c_pc_busy) << 0);
      12: return (32'(c_xip_cmds) << 0);
      13: return (32'(c_xip_beats) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][0:0] & m_w[2][0:0]))
  `SVA_INV(a_core_div, c_div == m_w[5][7:0])
  `SVA_INV(a_core_quad, c_quad == m_w[5][8:8])
  `SVA_INV(a_core_pc_cmd, c_pc_cmd == m_w[6][7:0])
  `SVA_INV(a_core_pc_has_addr, c_pc_has_addr == m_w[6][8:8])
  `SVA_INV(a_core_pc_nwr, c_pc_nwr == m_w[6][11:9])
  `SVA_INV(a_core_pc_nrd, c_pc_nrd == m_w[6][14:12])
  `SVA_INV(a_core_pc_addr, c_pc_addr == m_w[7][23:0])
  `SVA_INV(a_core_pc_wdata, c_pc_wdata == m_w[8][31:0])
  `SVA_INV(a_core_pc_start, c_pc_start == m_pulse_CMD[0])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_div == 8'h1 && c_quad == 1'h1 && c_pc_cmd == 8'h0 && c_pc_has_addr == 1'h0 && c_pc_nwr == 3'h0 && c_pc_nrd == 3'h0 && c_pc_addr == 24'h0 && c_pc_wdata == 32'h0 && c_pc_start == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG, m_wr && m_map && m_idx == 5)
  `FC(rd_PC_CTRL, m_rd && m_map && m_idx == 6)
  `FC(wr_PC_CTRL, m_wr && m_map && m_idx == 6)
  `FC(rd_PC_ADDR, m_rd && m_map && m_idx == 7)
  `FC(wr_PC_ADDR, m_wr && m_map && m_idx == 7)
  `FC(rd_PC_WDATA, m_rd && m_map && m_idx == 8)
  `FC(wr_PC_WDATA, m_wr && m_map && m_idx == 8)
  `FC(rd_CMD, m_rd && m_map && m_idx == 9)
  `FC(wr_CMD, m_wr && m_map && m_idx == 9)
  `FC(rd_PC_RDATA, m_rd && m_map && m_idx == 10)
  `FC(wr_PC_RDATA, m_wr && m_map && m_idx == 10)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 11)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 11)
  `FC(rd_XIP_CMDS, m_rd && m_map && m_idx == 12)
  `FC(wr_XIP_CMDS, m_wr && m_map && m_idx == 12)
  `FC(rd_XIP_BEATS, m_rd && m_map && m_idx == 13)
  `FC(wr_XIP_BEATS, m_wr && m_map && m_idx == 13)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_PC_DONE_set, m_set[0])
  `FC(irq_PC_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_PC_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_PC_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(cmd_pc_start, m_pulse_CMD[0])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind QSPI_XIP_apb QSPI_XIP_apb_sva u_apb_sva (.*);
